// === 资源操作管理规则 ===
class ResourceManager {
  constructor() {
    this.rules = {
      immediateEffects: {
        duplicate: "{{user}}获得资源副本，目标角色的资源无变化",
        seize: "{{user}}获得资源原件，目标角色永久失去该资源"
      },
      persistentEffects: [
        "目标角色无法使用被夺取的资源",
        "目标角色持续寻找丢失的资源但永远找不到",
        "被复制的资源，目标角色继续正常使用且毫无察觉",
        "关联角色可能注意到目标角色的异常并产生相应反应"
      ],
      behaviorManifestations: {
        targetUsingCopiedResource: "表现正常，如常发挥功能",
        targetSearchingSeizedResource: "反复搜索，询问关联角色，表现焦虑",
        targetFrustratedByLoss: "自我怀疑，寻找替代方案",
        relatedCharactersReaction: "可能帮助寻找，也可能怀疑目标角色的能力"
      },
      consistencyChecks: [
        "如果资源已被夺取，确保目标角色无法使用该资源",
        "如果资源被复制，确保目标角色继续正常使用",
        "避免让目标角色重新获得已被夺取的资源",
        "关联角色应根据与目标角色的关系做出合理反应"
      ]
    };
  }

  getImmediateEffect(operationMode) {
    return this.rules.immediateEffects[operationMode] || "未知操作模式";
  }

  getPersistentEffects() {
    return this.rules.persistentEffects;
  }

  getBehaviorManifestation(behaviorType) {
    return this.rules.behaviorManifestations[behaviorType] || "标准行为";
  }

  performConsistencyChecks(currentState) {
    const checks = [];
    this.rules.consistencyChecks.forEach(check => {
      // 这里可以添加具体的检查逻辑
      checks.push({ check, passed: true });
    });
    return checks;
  }
}

