// 同步掠夺系统 - 优化函数库定义

// === 全局状态管理器 ===
const systemState = {
  target_person: "{{char}}",  // 目标角色
  resources: [],
  relationships: [],
  socialStatus: [],
  opportunities: [],
  causalityLoad: 0,
  lastUpdate: "等待初始化"
};

// === 事件总线 - 模块间通信 ===
const eventBus = {
  events: {},

  on(event, callback) {
    if (!this.events[event]) this.events[event] = [];
    this.events[event].push(callback);
  },

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
};

// === 统一状态更新函数 ===
function updateSystemState(category, data, operationType) {
  switch(category) {
    case 'resources':
      if (operationType === 'seize') {
        systemState.resources = systemState.resources.filter(r => r !== data);
        // 触发资源被夺取事件 - 影响目标角色和关联角色
        eventBus.emit('resource_seized', { 
          resource: data, 
          target_person: systemState.target_person,
          operationType: operationType 
        });
      }
      break;

    case 'relationships':
      systemState.relationships = systemState.relationships.filter(r => !r.includes(data));
      // 触发关系改变事件 - 影响目标角色和关联角色
      eventBus.emit('relationship_changed', { 
        relationship: data, 
        target_person: systemState.target_person,
        operationType: operationType 
      });
      break;

    case 'socialStatus':
      systemState.socialStatus = systemState.socialStatus.filter(s => s !== data);
      // 触发地位改变事件 - 影响目标角色和关联角色
      eventBus.emit('status_changed', { 
        status: data, 
        target_person: systemState.target_person,
        operationType: operationType 
      });
      break;

    case 'opportunities':
      systemState.opportunities = systemState.opportunities.filter(o => !o.includes(data));
      // 触发机遇拦截事件 - 影响目标角色和关联角色
      eventBus.emit('opportunity_intercepted', { 
        opportunity: data, 
        target_person: systemState.target_person,
        operationType: operationType 
      });
      break;
  }

  // 更新因果负载
  systemState.causalityLoad = Math.min(100, systemState.causalityLoad + 5);
  systemState.lastUpdate = "刚刚";

  // 自动更新面板
  display_panel();
}

// === 1. 资源操作函数 ===
function transfer_resource(resource_name, operation_mode = "duplicate") {
  /**
   * @param {string} resource_name - 资源名（如："家传宝剑"、"内力修为"）
   * @param {string} operation_mode - "duplicate"（复制）或 "seize"（夺取）
   * @returns {object} 操作确认信息
   * 效果：{{user}}获得资源，目标角色受到影响，关联角色可能产生连锁反应
   */

  updateSystemState('resources', resource_name, operation_mode);

  return {
    success: true,
    message: `资源${operation_mode === 'seize' ? '夺取' : '复制'}成功: ${resource_name}`,
    operation: 'transfer_resource',
