// === 统一规则管理器 ===
class RuleManager {
  constructor() {
    this.resourceManager = new ResourceManager();
    this.relationshipManager = new RelationshipManager();
    this.statusManager = new StatusManager();
    this.opportunityManager = new OpportunityManager();
  }

  // 执行所有一致性检查
  performAllConsistencyChecks(currentState) {
    const results = {
      resource: this.resourceManager.performConsistencyChecks(currentState),
      relationship: this.relationshipManager.performConsistencyChecks(currentState),
      status: this.statusManager.performConsistencyChecks(currentState),
      opportunity: this.opportunityManager.performConsistencyChecks(currentState)
    };
    return results;
  }

  // 获取特定操作的效果描述
  getOperationEffects(operationType, specificOperation) {
    switch(operationType) {
      case 'resource':
        return {
          immediate: this.resourceManager.getImmediateEffect(specificOperation),
          persistent: this.resourceManager.getPersistentEffects()
        };
      case 'relationship':
        return {
          immediate: this.relationshipManager.getImmediateEffects(),
          persistent: this.relationshipManager.getPersistentEffects()
        };
      case 'status':
        return {
          immediate: this.statusManager.getImmediateEffects(),
          persistent: this.statusManager.getPersistentEffects()
        };
      case 'opportunity':
        return {
          immediate: this.opportunityManager.getImmediateEffects(),
          persistent: this.opportunityManager.getPersistentEffects()
        };
      default:
        return { immediate: "未知操作", persistent: [] };
    }
  }
}

